import { promises as fs } from 'node:fs';
for(const p of ['scripts/build.mjs','assets/atlas.css','admin/config.yml'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}. Repo kökünde çalıştır.`)});
const append=async(f,p,m)=>{let s=await fs.readFile(f,'utf8');if(!s.includes(m)){s+='\n'+await fs.readFile(p,'utf8');await fs.writeFile(f,s)}};
await append('scripts/build.mjs','v22-build-patch.txt','V22 Policy Timeline');await append('assets/atlas.css','v22-css-patch.txt','V22 Policy Timeline');await fs.copyFile('timeline.js','assets/timeline.js');
await fs.mkdir('content',{recursive:true});try{await fs.access('content/timeline.json')}catch{await fs.copyFile('timeline.json','content/timeline.json')}
let cfg=await fs.readFile('admin/config.yml','utf8');if(!cfg.includes('name: "timeline"')){const block=`\n      - name: "timeline"\n        label: "Politika Zaman Çizelgesi"\n        file: "content/timeline.json"\n        format: "json"\n        fields:\n          - label: "Olaylar"\n            name: "events"\n            widget: "list"\n            required: false\n            add_to_top: true\n            summary: "{{fields.display_date}} — {{fields.title}}"\n            fields:\n              - {label: "Başlangıç tarihi", name: "start_date", widget: "datetime", format: "YYYY-MM-DD", date_format: "DD.MM.YYYY", time_format: false}\n              - {label: "Ekranda gösterilecek tarih", name: "display_date", widget: "string", hint: "Örnek: 1991, 2023–2026 veya 1 Ekim 2023"}\n              - {label: "Başlık", name: "title", widget: "string"}\n              - {label: "Kategori", name: "category", widget: "select", options: ["İklim Diplomasisi", "Avrupa Birliği", "Türkiye", "Libya", "Körfez", "Suriye", "Batı Sahra", "Uluslararası Hukuk", "Enerji Güvenliği"]}\n              - {label: "Bölge", name: "region", widget: "string", required: false}\n              - {label: "Kısa açıklama", name: "summary", widget: "text"}\n              - {label: "Neden kırılma noktası?", name: "why_turning_point", widget: "text"}\n              - {label: "Önem seviyesi", name: "importance", widget: "select", options: ["ARKA PLAN", "ÖNEMLİ GELİŞME", "KIRILMA NOKTASI", "SİSTEM DEĞİŞİKLİĞİ"]}\n              - label: "Ana aktörler"\n                name: "actors"\n                widget: "list"\n                required: false\n                field: {label: "Aktör", name: "actor", widget: "string"}\n              - label: "Etkilenen alanlar"\n                name: "affected_areas"\n                widget: "list"\n                required: false\n                field: {label: "Alan", name: "area", widget: "string"}\n              - {label: "Birincil kaynak URL", name: "primary_source", widget: "string", required: false}\n              - label: "İlgili yayın slugları"\n                name: "related_publications"\n                widget: "list"\n                required: false\n                field: {label: "Slug", name: "slug", widget: "string", hint: "Örnek: irakta-milis-paradoksu"}\n              - {label: "Sitede göster", name: "visible", widget: "boolean", default: true, required: false}\n`;const marker='      - name: "profile"';if(cfg.includes(marker))cfg=cfg.replace(marker,block+'\n'+marker);else cfg+=block;await fs.writeFile('admin/config.yml',cfg)}
console.log('V22 kuruldu: ayrı timeline sayfası, filtreler ve admin olay yönetimi eklendi.');
